<template>
	<view class="container">
		<uv-navbar leftText="返回" :fixed="false" :title="TDetail.name+'的主页'" :safeAreaInsetTop="true">
			<template v-slot:left>
				<view class="uv-nav-slot">
					<uv-icon name="arrow-left" size="19" @click="back"></uv-icon>
					<uv-line direction="column" :hairline="false" length="16" margin="0 8px"></uv-line>
					<uv-icon name="home" size="20" @click="back"></uv-icon>
				</view>
			</template>
		</uv-navbar>

		<uni-card :is-shadow="true" shadow="0px 0px 3px 1px rgba(120, 195, 70, 0.8)">
			<!-- <text class="uni-body">这是一个基础卡片示例，内容较少，此示例展示了一个没有任何属性不带阴影的卡片。</text> -->

			<uni-row class="demo-uni-row" :width="nvueWidth">
				<uni-col :span="7">
					<uv-image :src="TDetail.photo" width="120rpx" height="120rpx" radius="10"
						@click="lookImage(TDetail.photo)"></uv-image>
				</uni-col>
				<uni-col :span="14">
					<view>
						<uv-text :text="TDetail.name" size="16"></uv-text>
					</view>
					<view style="margin-top: 10rpx;">
						<uv-text :text="huanshui()" size="15" type="info"></uv-text>
					</view>
					<view style="margin-top: 10rpx;">
						<uv-text :text="weishi()" size="12" type="info"></uv-text>
					</view>
				</uni-col>
				<uni-col :span="3">
					<view style="margin-top: 50rpx;">
						<uv-button type="success" :plain="true" :hairline="true" text="编辑" size="mini"
							@click="toEdit"></uv-button>
					</view>
				</uni-col>
			</uni-row>
		</uni-card>
		<!-- 详情展示 -->
		<uni-card :is-shadow="true" shadow="0px 0px 3px 1px rgba(120, 195, 70, 0.8)">
			<uv-subsection :list="list" mode="subsection" :current="current" activeColor="#5ac725"
				inactiveColor="#5ac725" @change="changeList">
			</uv-subsection>
		</uni-card>
		<!-- 0 -->
		<uni-card :is-shadow="true" shadow="0px 0px 3px 1px rgba(120, 195, 70, 0.8)" v-if="current==0">
			<view>
				<uv-list>
					<uv-list-item title="品种" :rightText="TDetail.variety"></uv-list-item>
					<uv-list-item title="尺寸" :rightText="TDetail.length + 'cm'"></uv-list-item>
					<uv-list-item title="克重" :rightText="TDetail.weight + 'g'"></uv-list-item>
					<uv-list-item title="到家时间" :rightText="getTime(TDetail.birthday)"></uv-list-item>
				</uv-list>
			</view>
		</uni-card>
		<!-- 1 -->
		<uni-card :is-shadow="true" shadow="0px 0px 3px 1px rgba(120, 195, 70, 0.8)" v-if="current==1">
			<template>
				<uv-steps dot direction="column" inactiveColor="#5ac725" activeColor="#5ac725">
					<uv-steps-item v-for="(item,index) in growthList" :key="index">
						<template v-slot:title>
							<image mode="aspectFit" :src="item.image" class="growth-img" @click="lookImage(item.image)">
							</image>
							<!-- 删除这条记录 -->
							<view class="growth-del" @click="delGrowth(item._id)">
								<uv-icon name="trash" color="#666" size="24"></uv-icon>
							</view>
							<view class="text-container">
								<text class="growth-text">{{item.length}}cm</text>
								<text class="growth-text">{{item.weight}}g</text>
							</view>
						</template>
						<template v-slot:desc>
							<text class="growth-data">{{getTime(item.createdAt)}}</text>
						</template>
					</uv-steps-item>
				</uv-steps>
			</template>
		</uni-card>

		<!-- 加载 -->
		<uv-toast ref="loading" :loading="true"></uv-toast>
	</view>
</template>

<script>
	export default {
		data() {
			return {
				openId: '',
				TDetail: {},
				//, '备注'
				list: ['爱龟信息', '成长记录'],
				current: 0,
				growthList: []
			}
		},
		computed:{
			
		},
		methods: {
			changeList(index) {
				this.current = index;
				if(index === 1){
					this.$refs.loading.show({
						type: 'loading',
						title: '正在加载',
						message: "正在加载",
						complete() {}
					})
					this.getPetDetail()
				}
			},
			getTime(timestamp, format = 'YYYY年MM月DD日') {
				const date = new Date(timestamp);
				const map = {
					'YYYY': date.getFullYear(),
					'MM': (date.getMonth() + 1).toString().padStart(2, '0'),
					'DD': date.getDate().toString().padStart(2, '0')
				};
				return format.replace(/YYYY|MM|DD/g, matched => map[matched]);
			},
			lookImage(image) {
				let images = []
				images.push(image)
				uni.previewImage({
					urls: images,
					longPressActions: {
						itemList: ['发送给朋友', '保存图片'],
						success: function(data) {
							console.log('选中了第' + (data.tapIndex + 1) + '个按钮,第' + (data.index + 1) + '张图片');
						},
						fail: function(err) {
							console.log(err.errMsg);
						}
					}
				});
			},
			back() {
				uni.navigateBack()
			},
			toEdit() {
				uni.navigateTo({
					url: "/pages/edit/edit"
				})
			},
			getPetDetail() {
				wx.cloud.callFunction({
					name: 'getGrowthRecord',
					data: {
						openId: this.openId,
						printId: this.TDetail._id
					},
					complete: res => {
						console.log('callFunction getGrowthRecord result: ', res)
						this.growthList = res.result.data
						this.$refs.loading.hide()
					}
				})
			},
			delGrowth(id){
				console.log(id)
				uni.showModal({
					title: '确认删除吗',
					content: '删除后将无法恢复,请确认',
					showCancel: true,
					cancelText: '取消',
					confirmText: '删除',
					confirmColor: '#FF1F87',
					success: (res) => {
						if (res.confirm) {
							this.$refs.loading.show({
								type: 'loading',
								title: '正在加载',
								message: "正在加载",
								complete() {}
							})
							wx.cloud.callFunction({
								name: 'deleteGrowthRecord',
								data: {
									_id:id
								},
								complete: res => {
									console.log('callFunction deleteGrowthRecord result: ', res)
									this.$refs.loading.hide()
									this.getPetDetail()
								}
							})
						}
					}
				})
			},
			weishi(){
				console.log(this.TDetail)
				if(this.TDetail?.shi == 0){
					return `今日已喂食`
				}else if(this.TDetail?.shi == 1){
					return `昨日已喂食`
				}else{
					return `${this.TDetail?.shi}天前已喂食`
				}
			},
			huanshui(){
				if(this.TDetail?.water == 0){
					return `今日已换水`
				}else if(this.TDetail?.water == 1){
					return `昨日已换水`
				}else{
					return `${this.TDetail?.water}天前已换水`
				}
			}
		},
		onLoad() {
			this.openId = this.$store.state.openId
			this.TDetail = this.$store.state.TDetail
			console.log(this.TDetail)
			// this.getPetDetail()

		},
		mounted() {

		}
	}
</script>

